from abc import ABCMeta, abstractmethod
from taf.ul.ettf.pdml_parser.parser import Enum, Message
from taf.ul.ettf.ta_matchers.matchers import MISSING_VALUE, OMIT_SUFFIX
import copy
import re


class ErrorAttributes(object):
    ERROR = 'error'
    MISSING = 'missing'
    SHOULD_BE_OMITTED = 'should be omitted'
    UNWANTED = 'unwanted'


class Value(object):
    def __init__(self, value):
        self.value = value

    def __str__(self):
        return '{}'.format(self.value)

    def __repr__(self):
        return str(self)

    def __eq__(self, other):
        if isinstance(other, type(self)):
            return self.value == other.value
        return False


class ErrorValueTemplate(Value):
    __metaclass__ = ABCMeta

    def __init__(self, expected, actual, identifier=None):
        self.expected = expected
        self.identifier = identifier
        super(ErrorValueTemplate, self).__init__(actual)

    def __str__(self):
        return 'Expected: {} | Got: {}'.format(self.expected, self.value)

    def __repr__(self):
        return str(self)

    def __hash__(self):
        return hash(self.expected)

    def __eq__(self, other):
        if isinstance(other, type(self)):
            return self.expected == other.expected and self.value == other.value
        return False

    @staticmethod
    @abstractmethod
    def generate_error_path(mismatch, mismatch_path):
        pass

    @staticmethod
    @abstractmethod
    def attribute():
        pass


class ErrorValue(ErrorValueTemplate):
    @staticmethod
    def generate_error_path(mismatch, mismatch_path):
        return [Node(name, [ErrorValue.attribute()], mismatch.identifier) for name in mismatch_path if name] + \
               [ErrorValue(mismatch.expected, mismatch.actual, mismatch.identifier)]

    @staticmethod
    def attribute():
        return ErrorAttributes.ERROR


class UnwantedValue(ErrorValueTemplate):
    @staticmethod
    def generate_error_path(mismatch, mismatch_path):
        return [Node(str(mismatch), [UnwantedValue.attribute()], mismatch.identifier)]

    @staticmethod
    def attribute():
        return ErrorAttributes.UNWANTED


class ShouldBeOmittedValue(ErrorValueTemplate):
    @staticmethod
    def generate_error_path(mismatch, mismatch_path):
        return [Node(name, [ShouldBeOmittedValue.attribute()], mismatch.identifier) for name in mismatch_path[:-2] if name] + \
               [Node(mismatch.actual, [ShouldBeOmittedValue.attribute()], mismatch.identifier)] + \
               [ShouldBeOmittedValue(mismatch.expected, mismatch.actual, mismatch.identifier)]

    @staticmethod
    def attribute():
        return ErrorAttributes.SHOULD_BE_OMITTED


class MissingValue(ErrorValueTemplate):
    @staticmethod
    def generate_error_path(mismatch, mismatch_path):
        return [Node(name, [MissingValue.attribute()], mismatch.identifier) for name in mismatch_path if name] + \
               [Node(mismatch.expected, [MissingValue.attribute()], mismatch.identifier)]

    @staticmethod
    def attribute():
        return ErrorAttributes.MISSING


class Node(object):
    def __init__(self, key, attributes=None, identifier=None):
        self.key = key
        self.attributes = attributes if attributes else []
        self.identifier = identifier

    def has(self, error_attribute):
        return error_attribute in self.attributes

    @property
    def pretty_attributes(self):
        return '<b>({})</b>'.format('|'.join(self.attributes))

    def __eq__(self, other):
        if isinstance(other, Node):
            return self.key == other.key
        if isinstance(other, str):
            return self.key == other
        return False

    def __hash__(self):
        return hash(self.key)

    def __str__(self):
        return '[{}]'.format(self.key)

    def __repr__(self):
        return str(self)

    def __add__(self, other):
        if isinstance(other, Node):
            assert self.key == other.key, 'Wrong keys!'
            return Node(self.key, list(set(self.attributes + other.attributes)), self.identifier)

        raise Exception('wrong type')


class PacketWithErrors(dict):
    def __setitem__(self, node, value):
        if not isinstance(node, Node):
            return

        if node.key in self:
            node = self._get_node(node.key) + node
            del self[node.key]

        super(PacketWithErrors, self).__setitem__(node, value)

    def _get_node(self, key):
        return [node for node in self.keys() if node.key == key][0]


class MismatchErrorPath(object):
    def __init__(self, identifier, error_path):
        self.identifier = identifier
        self.error_path = error_path


class PacketConverter(object):
    def __init__(self, packet, mismatches):
        self.packet = copy.deepcopy(self._prepare(packet))
        self.mismatch_error_paths = self._prepare_paths(mismatches)

    def convert(self):
        for mismatch_error_path in self.mismatch_error_paths:
            PacketApplier().apply(self.packet, mismatch_error_path.error_path, mismatch_error_path.identifier)
        return self.packet

    def _prepare_paths(self, mismatches):
        return [MismatchErrorPath(mismatch.identifier, self._prepare_error_path(mismatch)) for mismatch in mismatches]

    @staticmethod
    def _prepare_error_path(mismatch):
        if mismatch.actual == MISSING_VALUE:
            value_type = MissingValue
        elif mismatch.actual == 'present':
            value_type = UnwantedValue
        elif mismatch.expected.endswith(OMIT_SUFFIX):
            value_type = ShouldBeOmittedValue
        else:
            value_type = ErrorValue

        mismatch_path = re.split(r'[.\[\]]', mismatch.field())
        return value_type.generate_error_path(mismatch, mismatch_path)

    def _prepare(self, packet):
        if isinstance(packet, (Message, dict)) and not isinstance(packet, Enum):
            result = PacketWithErrors()
            for k, v in packet.items():
                result[Node(k)] = self._prepare(v)
            return result

        if isinstance(packet, list):
            return PacketWithErrors({Node(str(index)): self._prepare(e) for (index, e) in enumerate(packet)})

        return Value(packet)


class PacketApplier(object):
    def apply(self, packet, error_path, path_identifier):
        self._assert_error_path_correct(error_path)
        elem = error_path[0]

        if self._already_applied(elem, packet):
            return elem

        self._update_node_errors(elem, packet, path_identifier)

        if self._is_last_element_on(error_path):
            return self._apply_last_element_on_error_path(elem, packet)

        self._apply_next_element_on_error_path(elem, error_path, path_identifier, packet)
        return packet

    @staticmethod
    def _assert_error_path_correct(error_path):
        assert error_path, 'error_path should not be empty'

    @staticmethod
    def _already_applied(elem, packet):
        return isinstance(elem, ErrorValueTemplate) and isinstance(packet, Value)

    @staticmethod
    def _is_last_element_on(error_path):
        return len(error_path) == 1

    def _update_node_errors(self, elem, packet, path_identifier):
        if isinstance(elem, ErrorValueTemplate) and isinstance(packet, PacketWithErrors):
            if elem.value in packet:
                self._update_packet_node(elem, packet, path_identifier, elem.attribute())

    @staticmethod
    def _update_packet_node(elem, packet, path_identifier, attribute):
        node = [node for node in packet.keys() if node.key == elem.value][0]
        node += Node(elem.value, [attribute], path_identifier)
        packet[node] = packet[node]

    def _apply_next_element_on_error_path(self, elem, error_path, path_identifier, packet):
        if elem in packet:
            packet[elem] = self.apply(packet[elem], error_path[1:], path_identifier)
        else:
            packet[elem] = self.apply(PacketWithErrors(), error_path[1:], path_identifier)

    @staticmethod
    def _apply_last_element_on_error_path(elem, packet):
        if elem not in packet:
            packet[elem] = PacketWithErrors()
            return packet
        if isinstance(elem, Node):
            packet[elem] = packet[elem]
            return packet
        return elem
